using System;using System.IO;using System.Text.Json;using System.Collections.Generic;using Exoduser.UnityPort.Core;
class PoiseProgram{
 static List<object> rows=new List<object>();static int failures;static void Check(bool pass,string name){rows.Add(new{name,passed=pass});if(!pass)failures++;}
 static Simulation Make(out EnemyState e){var s=new Simulation(new SimulationConfig());s.Random01=()=>.5;e=s.SpawnNormalEnemy(200,0);e.Poise=0;e.MaxPoise=100;e.Stunned=1;s.CanMove=(x,y,r)=>false;return s;}
 static void Step(Simulation s)=>s.Tick(0,0,100,0,false,false);
 static float Regen(EnemyState e){var f=typeof(EnemyState).GetField("PoiseRegenTicks");return f==null?-999:Convert.ToSingle(f.GetValue(e));}
 static int Main(string[] args){using var doc=JsonDocument.Parse(File.ReadAllText(args[1]));var root=doc.RootElement;var s=Make(out var e);Step(s);Check(e.Stunned==root.GetProperty("expiry").GetProperty("stunned").GetSingle()&&e.Poise==root.GetProperty("expiry").GetProperty("poise").GetSingle(),"source34456 ordinary stun expiry does not restore full poise");Check(Regen(e)==1,"source expiry frame begins normal regeneration tick1");for(int i=0;i<198;i++)Step(s);Check(e.Poise==0&&Regen(e)==199,"source no ordinary regen before200 eligible frames");Step(s);Check(e.Poise==15&&Regen(e)==0,"source200 eligible frames add15percent and reset timer");for(int i=0;i<200;i++)Step(s);Check(e.Poise==30&&Regen(e)==0,"source400 eligible frames add second15percent");s=Make(out e);e.Stunned=2;Step(s);Check(e.Stunned==1&&e.Poise==0&&Regen(e)==0,"source stunned early return stops regen");s=Make(out e);e.Stunned=0;e.Poise=25;e.HitStun=2;var field=typeof(EnemyState).GetField("PoiseRegenTicks");if(field!=null)field.SetValue(e,199f);Step(s);Check(e.HitStun==1&&e.Poise==25&&Regen(e)==199,"source hitstun early return stops regen");var result=JsonSerializer.Serialize(new{scope="standalone_dotnet_source_prefix_not_Unity_runtime",passed=failures==0,failures,checks=rows},new JsonSerializerOptions{WriteIndented=true});File.WriteAllText(args[0],result);Console.WriteLine("POISE_RESULT "+rows.Count+" checks / "+failures+" failures");return failures==0?0:2;}
}
